#!/usr/bin/env node

// ==========================================================================
// CUSTOM DEMO FILE GENERATOR CLI
// ==========================================================================
// Generates individual custom demo files and automatically updates 
// custom-demo features.jsx and import.js
// Usage: node create-custom-demo-type.js <DemoName> --component=<ComponentName> [options]

