// ==========================================================================
// UTILITY FUNCTIONS
// ==========================================================================

/**
 * Smart template detection based on demo name
 */
function detectTemplate(demoName) {
  const name = demoName.toLowerCase();
  
  if (name.includes('basic')) return 'basic';
  if (name.includes('accessibility') || name.includes('accessible')) return 'accessibility';
  if (name.includes('disabled')) return 'disabled';
  if (name.includes('invalid') || name.includes('validation') || name.includes('error')) return 'invalid';
  
  return 'custom';
}

function replaceTemplateVariables(template, variables) {
  let result = template;
  
  Object.entries(variables).forEach(([key, value]) => {
    const regex = new RegExp(`{{${key}}}`, 'g');
    result = result.replace(regex, value || '');
  });
  
  return result;
}

function generateComponentVariations(componentName) {
  if (!componentName) return {};
  
  const pascalCase = componentName.charAt(0).toUpperCase() + componentName.slice(1);
  const camelCase = componentName.charAt(0).toLowerCase() + componentName.slice(1);
  const kebabCase = componentName.toLowerCase().replace(/([A-Z])/g, '-$1').toLowerCase();
  
  return {
    ComponentName: pascalCase,
    componentName: camelCase,
    'component-name': kebabCase,
    primereactName: kebabCase
  };
}

function generateDemoVariations(demoName) {
  if (!demoName) return {};
  
  const pascalCase = demoName.charAt(0).toUpperCase() + demoName.slice(1);
  const camelCase = demoName.charAt(0).toLowerCase() + demoName.slice(1);
  
  return {
    DemoName: pascalCase,
    demoName: camelCase
  };
}

// ==========================================================================
// FILE UPDATE FUNCTIONS
// ==========================================================================

function updateImportFile(importFilePath, demoName, componentName) {
  if (!fs.existsSync(importFilePath)) {
    console.error(`❌ Import file not found: ${importFilePath}`);
    return false;
  }

  const content = fs.readFileSync(importFilePath, 'utf8');
  const demoVariations = generateDemoVariations(demoName);
  const variations = generateComponentVariations(componentName);
  
  // Add demo export if not exists (organized by component name)
  const demoExport = `export { default as ${demoVariations.DemoName}Demo } from '../../custom-components/${variations.ComponentName}/${demoVariations.DemoName}';`;
  const sourceExport = `export { default as ${demoVariations.DemoName}Source } from '../../custom-components/${variations.ComponentName}/${demoVariations.DemoName}/${demoVariations.DemoName}.jsx?raw';`;
  
  let updatedContent = content;
  
  // Add demo export
  if (!content.includes(`${demoVariations.DemoName}Demo`)) {
    // Try to find a good place to insert (after existing exports)
    const exportRegex = /(export \{ default as \w+Demo \} from.*?;)/g;
    const matches = [...content.matchAll(exportRegex)];
    
    if (matches.length > 0) {
      // Insert after last demo export
      const lastMatch = matches[matches.length - 1];
      updatedContent = content.replace(
        lastMatch[0],
        `${lastMatch[0]}\n${demoExport}`
      );
    } else {
      // No existing exports, add at the beginning after comments
      const commentEnd = content.indexOf('//');
      if (commentEnd !== -1) {
        const nextLine = content.indexOf('\n', commentEnd);
        if (nextLine !== -1) {
          updatedContent = content.slice(0, nextLine + 1) + 
                         `${demoExport}\n` + 
                         content.slice(nextLine + 1);
        } else {
          updatedContent = content + `\n${demoExport}`;
        }
      } else {
        updatedContent = `${demoExport}\n${content}`;
      }
    }
  }
  
  // Add source export if not exists
  if (!updatedContent.includes(`${demoVariations.DemoName}Source`)) {
    const sourceExportRegex = /(export \{ default as \w+Source \} from.*?;)/g;
    const sourceMatches = [...updatedContent.matchAll(sourceExportRegex)];
    
    if (sourceMatches.length > 0) {
      // Insert after last source export
      const lastMatch = sourceMatches[sourceMatches.length - 1];
      updatedContent = updatedContent.replace(
        lastMatch[0],
        `${lastMatch[0]}\n${sourceExport}`
      );
    } else {
      // Add at the end
      updatedContent += `\n${sourceExport}`;
    }
  }
  
  fs.writeFileSync(importFilePath, updatedContent);
  console.log(`✅ Updated: ${importFilePath}`);
  return true;
}

function updateFeaturesFile(featuresFilePath, demoName, componentName, description) {
  if (!fs.existsSync(featuresFilePath)) {
    console.error(`❌ Features file not found: ${featuresFilePath}`);
    return false;
  }

  const content = fs.readFileSync(featuresFilePath, 'utf8');
  const variations = generateComponentVariations(componentName);
  const demoVariations = generateDemoVariations(demoName);
  
  // Add import if not exists
  const demoImport = `${demoVariations.DemoName}Demo,`;
  const sourceImport = `${demoVariations.DemoName}Source,`;
  
  let updatedContent = content;
  
  // Add demo import
  if (!content.includes(`${demoVariations.DemoName}Demo`)) {
    // Find the import section
    const importRegex = /(import \{[\s\S]*?)(\} from '\.\/import';)/;
    const match = content.match(importRegex);
    
    if (match) {
      // Check if there's already a demo import section
      if (match[1].includes('CustomBasicDemo')) {
        // Add after existing demo imports
        updatedContent = content.replace(
          /(CustomBasicDemo,?\s*)/,
          `$1${demoImport}\n    `
        );
      } else {
        // Add before the closing brace
        updatedContent = content.replace(
          importRegex,
          `$1    ${demoImport}\n$2`
        );
      }
    }
  }
  
  // Add source import
  if (!updatedContent.includes(`${demoVariations.DemoName}Source`)) {
    const importRegex = /(import \{[\s\S]*?)(\} from '\.\/import';)/;
    const match = updatedContent.match(importRegex);
    
    if (match && !match[1].includes(`${demoVariations.DemoName}Source`)) {
      updatedContent = updatedContent.replace(
        importRegex,
        `$1    ${sourceImport}\n$2`
      );
    }
  }
  
  // Escape description for JSX content attribute (HTML entities)
  const escapedDescription = description
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
  
  // Add feature item
  const featureItem = `,
    {
        id: "custom-${demoVariations.demoName}",
        sectionNav: "${demoVariations.DemoName}",
        sectionDesc: <RichText as="span" content="${escapedDescription}" />,
        demo: (
            <CodePreview 
                demo={<${demoVariations.DemoName}Demo />} 
                source={${demoVariations.DemoName}Source} 
                snippetName="custom-${demoVariations.demoName}" 
                language="jsx" 
            />
        ),
    }`;
  
  if (!updatedContent.includes(`id: "custom-${demoVariations.demoName}"`)) {
    // Find the CustomFeatureItems array - match the array name dynamically
    const componentNameVar = `Custom${variations.ComponentName}FeatureItems`;
    
    // Pattern: Match from array start to closing bracket (non-greedy, multiline)
    // This handles both empty arrays and arrays with items
    const customFeaturesRegex = new RegExp(
      `(const ${componentNameVar} = \\[[\\s\\S]*?)(\\]\\s*)`,
      'm'
    );
    
    const match = updatedContent.match(customFeaturesRegex);
    
    if (match) {
      const arrayStart = match[1]; // Everything up to (but not including) the closing bracket
      const closingBracket = match[2]; // The closing bracket and any whitespace after
      
      // Check if array is empty by looking at what's between [ and ]
      const arrayBody = arrayStart.replace(new RegExp(`const\\s+${componentNameVar}\\s*=\\s*\\[`), '').trim();
      const isEmpty = arrayBody.length === 0 || arrayBody === '';
      
      if (isEmpty) {
        // Array is empty, add first item without leading comma
        const newFeature = featureItem.replace(/^,\s*/, '    ');
      updatedContent = updatedContent.replace(
        customFeaturesRegex,
          `$1${newFeature}\n$2`
      );
    } else {
        // Array has items, add with leading comma
        updatedContent = updatedContent.replace(
          customFeaturesRegex,
          `$1${featureItem}\n$2`
        );
      }
      
      console.log(`✅ Added feature "${demoVariations.DemoName}" to ${componentNameVar}`);
    } else {
      console.error(`❌ Could not find ${componentNameVar} array in features.jsx`);
      console.error(`   Expected pattern: const ${componentNameVar} = [...]`);
      return false;
    }
  } else {
    console.log(`ℹ️  Feature "custom-${demoVariations.demoName}" already exists in features.jsx`);
  }
  
  fs.writeFileSync(featuresFilePath, updatedContent);
  console.log(`✅ Updated: ${featuresFilePath}`);
  return true;
}

// ==========================================================================
// ULS PACKAGE FINDER
// ==========================================================================

function findULSPackage() {
  const projectRoot = process.cwd();
  
  // Try to find ULS package in different locations
  const candidates = [
    // If ULS is installed as npm package
    path.resolve(projectRoot, 'node_modules/uls-v2'),
    // If running from ULS development workspace
    path.resolve(__dirname, '..'),
    // Alternative package name
    path.resolve(projectRoot, 'node_modules/@uls/v2'),
  ];
  
  for (const candidate of candidates) {
    const primereactPath = path.join(candidate, 'src/libs/uls-primereact');
    if (fs.existsSync(primereactPath)) {
      return candidate;
    }
  }
  
  return null;
}

function getULSVersion() {
  const ulsPackage = findULSPackage();
  if (!ulsPackage) {
    return 'unknown';
  }
  
  const packageJsonPath = path.join(ulsPackage, 'package.json');
  if (fs.existsSync(packageJsonPath)) {
    try {
      const pkg = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
      return pkg.version || 'unknown';
    } catch (error) {
      return 'unknown';
    }
  }
  return 'unknown';
}

