function ensureCustomDemoPage(componentName, primereactPath) {
  const variations = generateComponentVariations(componentName);
  const pageFolderName = `${variations.ComponentName}Page`;
  
  const customDemoPath = path.join(primereactPath, 'src/custom-demo');
  const componentPagePath = path.join(customDemoPath, pageFolderName);
  const featuresFilePath = path.join(componentPagePath, 'features.jsx');
  const importFilePath = path.join(componentPagePath, 'import.js');
  const metaFilePath = path.join(componentPagePath, 'meta.js');
  
  // Check if all required files exist
  const featuresExists = fs.existsSync(featuresFilePath);
  const importExists = fs.existsSync(importFilePath);
  const metaExists = fs.existsSync(metaFilePath);
  
  if (featuresExists && importExists && metaExists) {
    return false; // Already exists, no need to create
  }
  
  console.log(`\n📦 Custom demo page not found. Creating structure for ${componentName}...`);
  
  // Create directory
  if (!fs.existsSync(componentPagePath)) {
    fs.mkdirSync(componentPagePath, { recursive: true });
    console.log(`📁 Created directory: ${path.relative(process.cwd(), componentPagePath)}`);
  }
  
  // Try to read master meta.js to get metadata
  const masterMetaPath = path.join(primereactPath, 'src/Pages/Documentation/UiComponents', pageFolderName, 'meta.js');
  let masterMeta = null;
  if (fs.existsSync(masterMetaPath)) {
    try {
      const masterMetaContent = fs.readFileSync(masterMetaPath, 'utf8');
      // Extract values using regex (simple approach)
      const categoryMatch = masterMetaContent.match(/category:\s*['"]([^'"]+)['"]/);
      const subCategoryMatch = masterMetaContent.match(/subCategory:\s*['"]([^'"]+)['"]/);
      const iconMatch = masterMetaContent.match(/icon:\s*['"]([^'"]+)['"]/);
      const importMsgMatch = masterMetaContent.match(/importMsg:\s*["']([^"']+)["']/);
      const subHeaderMatch = masterMetaContent.match(/subHeader:\s*['"]([^'"]+)['"]/);
      const routeBaseMatch = masterMetaContent.match(/routeBase:\s*['"]([^'"]+)['"]/);
      
      masterMeta = {
        category: categoryMatch ? categoryMatch[1] : 'Components',
        subCategory: subCategoryMatch ? subCategoryMatch[1] : 'General',
        icon: iconMatch ? iconMatch[1] : 'pi pi-circle',
        importMsg: importMsgMatch ? importMsgMatch[1] : `import { ${variations.ComponentName} } from 'primereact/${variations.primereactName}'`,
        subHeader: subHeaderMatch ? subHeaderMatch[1] : `${variations.ComponentName} is a flexible container component.`,
        routeBase: routeBaseMatch ? routeBaseMatch[1] : `/${variations.componentName}`
      };
    } catch (error) {
      console.warn(`⚠️  Could not parse master meta.js: ${error.message}`);
    }
  }
  
  // Get ULS version
  const ulsVersion = getULSVersion();
  const timestamp = new Date().toISOString();
  
  // Template variables
  const templateVars = {
    ...variations,
    ULS_VERSION: ulsVersion,
    TIMESTAMP: timestamp,
    CATEGORY: masterMeta?.category || 'Components',
    SUBCATEGORY: masterMeta?.subCategory || 'General',
    ICON: masterMeta?.icon || 'pi pi-circle',
    IMPORT_MSG: masterMeta?.importMsg || `import { ${variations.ComponentName} } from 'primereact/${variations.primereactName}'`,
    SUBHEADER: masterMeta?.subHeader || `${variations.ComponentName} is a flexible container component.`,
    routeBase: masterMeta?.routeBase || variations.componentName
  };
  
  // Create features.jsx if missing
  if (!featuresExists) {
    const featuresContent = replaceTemplateVariables(CUSTOM_DEMO_TEMPLATES.features, templateVars);
    fs.writeFileSync(featuresFilePath, featuresContent, 'utf8');
    console.log(`✅ Created: ${path.relative(process.cwd(), featuresFilePath)}`);
  }
  
  // Create import.js if missing
  if (!importExists) {
    const importContent = replaceTemplateVariables(CUSTOM_DEMO_TEMPLATES.import, templateVars);
    fs.writeFileSync(importFilePath, importContent, 'utf8');
    console.log(`✅ Created: ${path.relative(process.cwd(), importFilePath)}`);
  }
  
  // Create meta.js if missing
  if (!metaExists) {
    const metaContent = replaceTemplateVariables(CUSTOM_DEMO_TEMPLATES.meta, templateVars);
    fs.writeFileSync(metaFilePath, metaContent, 'utf8');
    console.log(`✅ Created: ${path.relative(process.cwd(), metaFilePath)}`);
  }
  
  // Create version tracking folder
  const syncPath = path.join(componentPagePath, '.uls-sync');
  if (!fs.existsSync(syncPath)) {
    fs.mkdirSync(syncPath, { recursive: true });
    
    const versionInfo = {
      ulsVersion: ulsVersion,
      demoVersion: "1.0.0",
      lastSync: timestamp,
      history: [
        {
          demoVersion: "1.0.0",
          ulsVersion: ulsVersion,
          created: timestamp,
          changes: "Initial custom demo page creation"
        }
      ],
      masterSnapshot: []
    };
    
    fs.writeFileSync(
      path.join(syncPath, 'version.json'),
      JSON.stringify(versionInfo, null, 2),
      'utf8'
    );
  }
  
  return true; // Created
}

// ==========================================================================
// MAIN GENERATOR FUNCTION
// ==========================================================================

function generateCustomDemoFile(config) {
  const {
    demoName,
    componentName,
    template = 'custom',
    description = null
  } = config;

  // Auto-generate description if not provided
  const finalDescription = description || `The <code>${demoName}</code> demo shows ${demoName.toLowerCase()} usage of the ${componentName} component.`;

  const variations = generateComponentVariations(componentName);
  const demoVariations = generateDemoVariations(demoName);
  
  // Find uls-primereact directory
  const ulsPackage = findULSPackage();
  if (!ulsPackage) {
    throw new Error('ULS package not found. Make sure you are running from ULS workspace or uls-v2 is installed.');
  }
  
  const primereactPath = path.join(ulsPackage, 'src/libs/uls-primereact');
  if (!fs.existsSync(primereactPath)) {
    throw new Error(`uls-primereact not found at: ${primereactPath}`);
  }
  
  // Determine paths - custom-components folder organized by component name
  const customComponentsPath = path.join(primereactPath, 'src/custom-components');
  const componentFolderPath = path.join(customComponentsPath, variations.ComponentName);
  const demoComponentPath = path.join(componentFolderPath, demoVariations.DemoName);
  const demoFilePath = path.join(demoComponentPath, `${demoVariations.DemoName}.jsx`);
  
  // Create directories if they don't exist
  if (!fs.existsSync(componentFolderPath)) {
    fs.mkdirSync(componentFolderPath, { recursive: true });
    console.log(`📁 Created directory: ${path.relative(process.cwd(), componentFolderPath)}`);
  }
  
  if (!fs.existsSync(demoComponentPath)) {
    fs.mkdirSync(demoComponentPath, { recursive: true });
    console.log(`📁 Created directory: ${path.relative(process.cwd(), demoComponentPath)}`);
  }
  
  // Get template
  const templateContent = DEMO_TEMPLATES[template] || DEMO_TEMPLATES.custom;
  
  // Generate demo file
  const templateVars = {
    ...variations,
    ...demoVariations,
    DESCRIPTION: finalDescription
  };
  
  const demoContent = replaceTemplateVariables(templateContent, templateVars);
  
  // Write demo file
  fs.writeFileSync(demoFilePath, demoContent);
  console.log(`✅ Created: ${path.relative(process.cwd(), demoFilePath)}`);
  
  // Create index.js if it doesn't exist
  const indexFilePath = path.join(demoComponentPath, 'index.jsx');
  if (!fs.existsSync(indexFilePath)) {
    const indexContent = `export { default } from './${demoVariations.DemoName}';\n`;
    fs.writeFileSync(indexFilePath, indexContent);
    console.log(`✅ Created: ${path.relative(process.cwd(), indexFilePath)}`);
  }
  
  // Check and create custom demo page if it doesn't exist
  const customDemoPath = path.join(primereactPath, 'src/custom-demo');
  const componentPagePath = path.join(customDemoPath, `${variations.ComponentName}Page`);
  const importFilePath = path.join(componentPagePath, 'import.js');
  const featuresFilePath = path.join(componentPagePath, 'features.jsx');
  
  // Ensure custom demo page exists
  const wasCreated = ensureCustomDemoPage(componentName, primereactPath);
  
  if (wasCreated) {
    console.log(`\n✅ Custom demo page structure created for ${componentName}`);
  }
  
  // Now update the files
    console.log(`\n🔄 Updating custom demo page files...`);
    
    updateImportFile(importFilePath, demoName, componentName);
    updateFeaturesFile(featuresFilePath, demoName, componentName, finalDescription);
    
    console.log(`\n🎉 Successfully generated ${demoName} custom demo for ${componentName}!`);
  console.log(`📁 Demo file: ${path.relative(process.cwd(), demoFilePath)}`);
    console.log(`📝 Custom demo page updated automatically`);
  
  return {
    demoFilePath,
    componentPagePath,
    updated: fs.existsSync(componentPagePath)
  };
}

// ==========================================================================
// CLI INTERFACE
// ==========================================================================

function showHelp() {
  console.log(`
🚀 Custom Demo File Generator

Usage: node create-custom-demo-type.js <DemoName> --component=<ComponentName> [options]

Examples:
  node create-custom-demo-type.js Basic --component=Card
  node create-custom-demo-type.js Accessibility --component=Button
  node create-custom-demo-type.js Disabled --component=InputText
  node create-custom-demo-type.js Validation --component=InputText --description="Custom validation demo"

Options:
  --component=<name>     Component name (required)
  --template=<type>      Template type: basic, accessibility, disabled, invalid, custom (auto-detected)
  --description=<desc>   Description for the demo (auto-generated if not provided)

Smart Template Detection:
  - "Basic" → basic template
  - "Accessibility" → accessibility template  
  - "Disabled" → disabled template
  - "Invalid", "Validation", "Error" → invalid template
  - Others → custom template

Generated Files:
  📄 DemoName.jsx        - Custom demo component file (in src/custom-components/)
  📄 index.jsx          - Export file for demo component
  🔄 import.js          - Updated with new demo exports (in src/custom-demo/[Component]Page/)
  🔄 features.jsx       - Updated with new feature item (in src/custom-demo/[Component]Page/)

Note: Make sure you've run 'uls-create-custom-demo' first to create the custom demo page structure.
    `);
}

function main() {
  const args = process.argv.slice(2);
  
  if (args.length === 0 || args[0] === '--help' || args[0] === '-h') {
    showHelp();
    return;
  }

  const demoName = args[0];
  const options = {};

  // Parse options
  args.slice(1).forEach(arg => {
    if (arg.startsWith('--')) {
      const [key, value] = arg.substring(2).split('=');
      options[key] = value;
    }
  });

  // Validate required options
  if (!options.component) {
    console.error('❌ Error: --component is required');
    console.log('Usage: node create-custom-demo-type.js <DemoName> --component=<ComponentName>');
    process.exit(1);
  }

  try {
    // Smart template detection if not explicitly provided
    const template = options.template || detectTemplate(demoName);
    
    console.log(`🚀 Generating ${demoName} custom demo for ${options.component}...`);
    console.log(`📋 Using template: ${template}`);
    console.log('');
    
    generateCustomDemoFile({
      demoName,
      componentName: options.component,
      template: template,
      description: options.description
    });
  } catch (error) {
    console.error('❌ Error generating custom demo:', error.message);
    if (error.stack) {
      console.error('\nStack trace:', error.stack);
    }
    process.exit(1);
  }
}

// Run the CLI
if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

export { generateCustomDemoFile };

